  --icon-size-sm: 16px;
  --icon-size-xs: 14px;
  --radius-100: 0.25rem;
  --radius-200: 0.5rem;
  --radius-300: 0.5rem;
  --radius-400: 0.75rem;
  --radius-full: 9999px;
  --radius-md: 0.5rem;
  --shadow-300: 0 6px 24px -6px rgba(0, 0, 0, 0.07);
